import java.util.*;
public class MonoalphabeticCipher {public static void main(String[]z){Scanner sc=new Scanner(System.in);System.out.print("Enter plaintext: ");String p=sc.nextLine().toUpperCase();char[] key="ABCDEFGHIJKLMNOPQRSTUVWXYZ".toCharArray();Random r=new Random();for(int i=25;i>0;i--){int j=r.nextInt(i+1);char t=key[i];key[i]=key[j];key[j]=t;}String alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZ",mapping=new String(key);System.out.println("Key used: "+mapping);StringBuilder c=new StringBuilder(),d=new StringBuilder();for(char x:p.toCharArray()){int i=alphabet.indexOf(x);c.append(i>=0?mapping.charAt(i):x);}for(char x:c.toString().toCharArray()){int i=mapping.indexOf(x);d.append(i>=0?alphabet.charAt(i):x);}System.out.println("Ciphertext: "+c);System.out.println("Decrypted: "+d);}}
